     * @param array|null $options
     * @throws InvalidArgumentException on argument parsing errors.
     */
    final public function __construct(?array $options = null) {}

    /**
 * <div id="mongodb-driver-bulkwritecommand.count" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\BulkWriteCommand::count</h1>  <p class="verinfo">(mongodb &gt;=2.1.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\BulkWriteCommand::count</span> — <span class="dc-title">Count number of write operations in the BulkWriteCommand</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-bulkwritecommand.count-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\BulkWriteCommand::count</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></div>  <p class="simpara">   Returns the number of write operations added to the   <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-bulkwritecommand.php" class="classname">MongoDB\Driver\BulkWriteCommand</a></span> object.  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-bulkwritecommand.count-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-bulkwritecommand.count-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns number of write operations added to the   <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-bulkwritecommand.php" class="classname">MongoDB\Driver\BulkWriteCommand</a></span> object.  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-bulkwritecommand.count-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>  </ul> </div> <div class="refsect1 examples" id="refsect1-mongodb-driver-bulkwritecommand.count-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">MongoDB\Driver\BulkWriteCommand::count()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br>\$bulk </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\BulkWriteCommand</span><span style="color: #007700">;<br></span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">insertOne</span><span style="color: #007700">(</span><span style="color: #DD0000">'db.coll'</span><span style="color: #007700">, [</span><span style="color: #DD0000">'_id' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #DD0000">'x' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">1</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">insertOne</span><span style="color: #007700">(</span><span style="color: #DD0000">'db.coll'</span><span style="color: #007700">, [</span><span style="color: #DD0000">'_id' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #DD0000">'x' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">2</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">updateOne</span><span style="color: #007700">(</span><span style="color: #DD0000">'db.coll'</span><span style="color: #007700">, [</span><span style="color: #DD0000">'x' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">2</span><span style="color: #007700">], [</span><span style="color: #DD0000">'\$set' </span><span style="color: #007700">=&gt; [</span><span style="color: #DD0000">'x' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">1</span><span style="color: #007700">]]);<br></span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">deleteMany</span><span style="color: #007700">(</span><span style="color: #DD0000">'db.coll'</span><span style="color: #007700">, [</span><span style="color: #DD0000">'x' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">1</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">count</span><span style="color: #007700">(</span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">));<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">int(4)</blockquote></div>   </div>  </div> </div></div>
 * 
