    /**
 * <div id="mongodb-driver-bulkwritecommand.updatemany" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\BulkWriteCommand::updateMany</h1>  <p class="verinfo">(mongodb &gt;=2.1.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\BulkWriteCommand::updateMany</span> — <span class="dc-title">Add an updateMany operation</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-bulkwritecommand.updatemany-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\BulkWriteCommand::updateMany</strong></span>(<br>&nbsp;&nbsp;&nbsp;&nbsp;<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$namespace</span></span>,<br>&nbsp;&nbsp;&nbsp;&nbsp;<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.object.php" class="type object" style="color:#EAB766">object</a></span></span> <span class="parameter" style="color:#3A95FF">\$filter</span></span>,<br>&nbsp;&nbsp;&nbsp;&nbsp;<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.object.php" class="type object" style="color:#EAB766">object</a></span></span> <span class="parameter" style="color:#3A95FF">\$update</span></span>,<br>&nbsp;&nbsp;&nbsp;&nbsp;<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></span> <span class="parameter" style="color:#3A95FF">\$options</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span><br>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="simpara">   Add an updateMany operation to the   <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-bulkwritecommand.php" class="classname">MongoDB\Driver\BulkWriteCommand</a></span>. All documents   matching <span class="parameter" style="color:#3A95FF">filter</span> in the collection identified by   <span class="parameter" style="color:#3A95FF">namespace</span> will be updated.  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-bulkwritecommand.updatemany-parameters">  <h3 class="title">参数</h3>  <dl>          <dt><span class="parameter" style="color:#3A95FF">namespace</span> (<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>)</dt>    <dd>     <span class="simpara">      A fully qualified namespace (e.g. <span class="literal">"databaseName.collectionName"</span>).     </span>    </dd>             <dt><span class="parameter" style="color:#3A95FF">filter</span> (<span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.object.php" class="type object" style="color:#EAB766">object</a></span></span>)</dt>    <dd>     <span class="simpara">      The <a href="https://www.mongodb.com/docs/manual/tutorial/query-documents/" class="link external">»&nbsp;query predicate</a>.      An empty predicate will match all documents in the collection.     </span>     <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:       <span class="simpara">       When evaluating query criteria, MongoDB compares types and values according to its own <a href="https://www.mongodb.com/docs/manual/reference/bson-type-comparison-order/" class="link external">»&nbsp;comparison rules for BSON types</a>, which differs from PHP's <a href="https://php.net/manual/zh/types.comparisons.php" class="link">comparison</a> and <a href="https://php.net/manual/zh/language.types.type-juggling.php" class="link">type juggling</a> rules. When matching a special BSON type the query criteria should use the respective <a href="https://php.net/manual/zh/mongodb.bson.php" class="link">BSON class</a> (e.g. use <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-bson-objectid.php" class="classname">MongoDB\BSON\ObjectId</a></span> to match an <a href="https://www.mongodb.com/docs/manual/reference/bson-types/#objectid" class="link external">»&nbsp;ObjectId</a>).      </span>     </p></blockquote>    </dd>          <dt><span class="parameter" style="color:#3A95FF">update</span> (<span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.object.php" class="type object" style="color:#EAB766">object</a></span></span>)</dt>    <dd>     <span class="simpara">      A document containing either update operators (e.g.      <span class="literal">\$set</span>) or an      <a href="https://www.mongodb.com/docs/manual/reference/command/update/#update-with-an-aggregation-pipeline" class="link external">»&nbsp;aggregation pipeline</a>.     </span>    </dd>          <dt><span class="parameter" style="color:#3A95FF">options</span></dt>    <dd>     <p class="para">      </p><table class="doctable table">       <caption><strong>options</strong></caption>               <thead>         <tr>          <th>Option</th>          <th>Type</th>          <th>Description</th>          <th>Default</th>         </tr>        </thead>        <tbody class="tbody">         <tr>          <td>arrayFilters</td>          <td><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></td>          <td>           <span class="simpara">            An array of filter documents that determines which array elements to            modify for an update operation on an array field. See            <a href="https://www.mongodb.com/docs/manual/reference/command/update/#update-command-arrayfilters" class="link external">»&nbsp;Specify arrayFilters for Array Update Operations</a>            in the MongoDB manual for more information.           </span>          </td>         </tr>                  <tr>          <td>collation</td>          <td><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.object.php" class="type object" style="color:#EAB766">object</a></span></span></td>          <td>           <span class="simpara">            <a href="https://www.mongodb.com/docs/upcoming/reference/collation/" class="link external">»&nbsp;Collation</a> allows users to specify language-specific rules for string comparison, such as rules for lettercase and accent marks. When specifying collation, the <span class="literal">"locale"</span> field is mandatory; all other collation fields are optional. For descriptions of the fields, see <a href="https://www.mongodb.com/docs/upcoming/reference/collation/#collation-document" class="link external">»&nbsp;Collation Document</a>.           </span>           <span class="simpara">            If the collation is unspecified but the collection has a default collation, the operation uses the collation specified for the collection. If no collation is specified for the collection or for the operation, MongoDB uses the simple binary comparison used in prior versions for string comparisons.           </span>           <span class="simpara">            This option is available in MongoDB 3.4+ and will result in an exception at execution time if specified for an older server version.           </span>          </td>         </tr>         <tr>          <td>hint</td>          <td><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.object.php" class="type object" style="color:#EAB766">object</a></span></span></td>          <td>           <span class="simpara">            Index specification. Specify either the index name as a string or            the index key pattern. If specified, then the query system will only            consider plans using the hinted index.           </span>          </td>         </tr>         <tr>          <td>upsert</td>          <td><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></td>          <td>           If <span class="parameter" style="color:#3A95FF">filter</span> does not match an existing document,           insert a <em>single</em> document. The document will be           created by applying operators in <span class="parameter" style="color:#3A95FF">update</span> to any           field values in <span class="parameter" style="color:#3A95FF">filter</span>.          </td>          <td><strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong></td>         </tr>        </tbody>             </table>         </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-bulkwritecommand.updatemany-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   没有返回值。  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-bulkwritecommand.updatemany-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>  </ul> </div> <div class="refsect1 examples" id="refsect1-mongodb-driver-bulkwritecommand.updatemany-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">MongoDB\Driver\BulkWriteCommand::updateMany()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br>\$manager </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\Manager</span><span style="color: #007700">;<br><br></span><span style="color: #9876AA">\$bulk </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\BulkWriteCommand</span><span style="color: #007700">;<br></span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">updateMany</span><span style="color: #007700">(</span><span style="color: #DD0000">'db.coll'</span><span style="color: #007700">, [</span><span style="color: #DD0000">'x' </span><span style="color: #007700">=&gt; [</span><span style="color: #DD0000">'\$gt' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">1</span><span style="color: #007700">]], [</span><span style="color: #DD0000">'\$set' </span><span style="color: #007700">=&gt; [</span><span style="color: #DD0000">'y' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">2</span><span style="color: #007700">]]);<br><br></span><span style="color: #9876AA">\$result </span><span style="color: #007700">= </span><span style="color: #9876AA">\$manager</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">executeBulkWriteCommand</span><span style="color: #007700">(</span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-bulkwritecommand.updatemany-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\BulkWriteCommand::replaceOne()} - Add a replaceOne operation</span></li>   <li><span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\BulkWriteCommand::updateMany()</strong></span></li>   <li><span class="methodname" style=